use vstd::prelude::*;

verus! {
    /// Finds an index of a minimum element in a[from..to),
    /// with 0 <= from < to <= a.len().
    ///
    /// Ensures:
    ///   from <= index < to
    ///   for all k in [from,to): a[index] <= a[k]
    fn find_min(a: &mut [i32], from: usize, to: usize) -> (index: usize)
        requires
            from < to,
            to <= a.len(),
        ensures
            from <= index && index < to,
            forall |k: usize| (from <= k && k < to) ==> a[index] <= a[k],
    {
        // Initialize our current best minimum to be at `from`,
        // and start scanning at from+1.
        let mut min_idx: usize = from;
        let mut i:       usize = from + 1;

        // Loop until i == to.
        // Invariant:
        //   1) min_idx is still in [from,to)
        //   2) from < to <= a.len()
        //   3) i <= to
        //   4) For every k in [from,i), a[min_idx] <= a[k].
        // When the loop exits, i == to, so (4) gives exactly
        //  forall k in [from,to): a[min_idx] <= a[k].
        while i < to
            invariant
                from <= min_idx && min_idx < to,
                to <= a.len(),
                i <= to,
                forall |k: usize| (from <= k && k < i) ==> a[min_idx] <= a[k],
            decreases to - i,
        {
            if a[i] < a[min_idx] {
                //
                // We have found a strictly smaller element at i.
                // We must show that now, if we set min_idx := i,
                // we restore the invariant
                //   forall k in [from,i): a[min_idx] <= a[k].
                //
                proof {
                    assert_forall(|k: usize| (from <= k && k < i) ==> a[i] <= a[k]) by {
                        // pick arbitrary k with from <= k < i
                        // from the old invariant we know a[min_idx] <= a[k]
                        assert(a[min_idx] <= a[k]);
                        // from the if-guard we know a[i] < a[min_idx]
                        assert(a[i] < a[min_idx]);
                        // so a[i] <= a[k]
                        assert(a[i] <= a[k]);
                    }
                }
                min_idx = i;
            } else {
                //
                // We did not update the minimum; we must show
                // a[min_idx] <= a[i] so that when we
                // bump i, the enlarged range [from,i+1) still
                // satisfies the invariant.
                //
                proof {
                    assert(a[min_idx] <= a[i]) by {
                        // from !(a[i] < a[min_idx]) we get a[min_idx] <= a[i]
                        assert(! (a[i] < a[min_idx]));
                    }
                }
            }

            // advance to the next element
            i = i + 1;
        }

        // At exit, i == to, so the invariant
        //   forall k in [from,i) ==> a[min_idx] <= a[k]
        // becomes
        //   forall k in [from,to) ==> a[min_idx] <= a[k],
        // which, together with from <= min_idx < to, is exactly our postcondition.
        min_idx
    }
}

